def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def is_pair(x):
        return isinstance(x, (list, tuple)) and len(x) >= 2

    def safe_pos(v, default):
        if is_pair(v):
            try:
                return [int(v[0]), int(v[1])]
            except Exception:
                pass
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_by(items, score_fn, default=None):
        best_item = default
        best_score = None
        for item in items or []:
            if not is_pair(item):
                continue
            try:
                s = score_fn(item)
            except Exception:
                continue
            if best_score is None or s < best_score:
                best_score = s
                best_item = item
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = safe_pos(observation.get("self_position"), [0, 0])
    ox, oy = safe_pos(observation.get("opponent_position"), [sx, sy])
    self_pos = [sx, sy]
    opp_pos = [ox, oy]
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [[0, 0], [0, max(0, gh - 1)], [max(0, gw - 1), 0], [max(0, gw - 1), max(0, gh - 1)]]
        target = best_by(corners, lambda c: manhattan(c, opp_pos), corners[0])
        move = step_away(self_pos, target)
        if move == [0, 0]:
            move = step_away(self_pos, opp_pos)
        return move

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        if not targets:
            move = step_away(self_pos, opp_pos) if manhattan(self_pos, opp_pos) <= 2 else [0, 0]
            return move
        def terr_score(cell):
            d_self = manhattan(cell, self_pos)
            d_opp = manhattan(cell, opp_pos)
            return d_self - (0.35 * d_opp)
        target = best_by(targets, terr_score, None)
        if target is None:
            return [0, 0]
        return step_toward(self_pos, target)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        def res_score(cell):
            d_self = manhattan(cell, self_pos)
            d_opp = manhattan(cell, opp_pos)
            return d_self - (0.25 * d_opp)
        target = best_by(resources, res_score, None)
        if target is not None:
            move = step_toward(self_pos, target)
            if manhattan(self_pos, opp_pos) <= 1 and move == step_toward(self_pos, opp_pos):
                move = step_away(self_pos, opp_pos)
            return move

    # Fallback: move away if threatened, otherwise toward opponent to stay active.
    if manhattan(self_pos, opp_pos) <= 1:
        return step_away(self_pos, opp_pos)
    return step_toward(self_pos, opp_pos)

